import csv, io, re
from datetime import date
from decimal import Decimal
from .models import Entry

_CURRENCY_RE = re.compile(r'[A-Z]{3}\Z')

def _normalize_currency(value):
    code = value.upper()
    if not _CURRENCY_RE.match(code):
        raise ValueError(f'Invalid currency code: {value!r}')
    return code

def parse_csv(text):
    return [Entry(row['account'], Decimal(row['amount']), date.fromisoformat(row['day']), row.get('status') or 'posted', _normalize_currency(row.get('currency'))) for row in csv.DictReader(io.StringIO(text))]
EOF
cat > ledger/summary.py << 'EOF'
from decimal import Decimal

def total(entries):
    return sum((e.amount for e in entries), Decimal('0'))

def totals_by_currency(entries, start=None, end=None, include_pending=False):
    if start is not None and end is not None and start > end:
        raise ValueError('start must not be after end')
    totals = {}
    for entry in entries:
        if not include_pending and entry.status != 'posted':
            continue
        if start is not None and entry.day < start:
            continue
        if end is not None and entry.day > end:
            continue
        totals[entry.currency] = totals.get(entry.currency, Decimal('0')) + entry.amount
    return totals
EOF
